from dataclasses import dataclass

from aerona.rules.groups import RuleGroup
from aerona.rules.model import rule


@dataclass(frozen=True)
class ReputationRules:
    decay_keep_pct: int = rule(75, 0, 100, RuleGroup.REPUTATION, "Share of past events' effect kept each epoch (%)")
    window_epochs: int = rule(8, 1, 100, RuleGroup.REPUTATION, "Epochs looked back when computing reputation")
    passion_window_epochs: int = rule(5, 1, 100, RuleGroup.REPUTATION, "Epochs looked back when reading passions")
    passion_points_per_action: int = rule(2, 1, 100, RuleGroup.REPUTATION, "Points each action adds to the related passion")
    max_passions: int = rule(3, 1, 8, RuleGroup.REPUTATION, "Maximum number of the god's passions")
    love_per_grace_event: int = rule(14, 0, 100, RuleGroup.REPUTATION, "Contribution of a blessing, pardon or ascension to love")
    fear_per_punish_event: int = rule(22, 0, 100, RuleGroup.REPUTATION, "Contribution of a lightning bolt, chain or exile to fear")
    love_per_message: int = rule(5, 0, 100, RuleGroup.REPUTATION, "Contribution of each non-threatening word from the god to love")
    fear_per_threat: int = rule(10, 0, 100, RuleGroup.REPUTATION, "Contribution of each threat from the god to fear")
    default_loyalty: int = rule(50, 0, 100, RuleGroup.REPUTATION, "Loyalty assumed for a son with no recorded loyalty")
    default_wrath: int = rule(20, 0, 100, RuleGroup.REPUTATION, "Wrath assumed for a son and the god with no recorded wrath")
    default_attention: int = rule(60, 0, 100, RuleGroup.REPUTATION, "Attention assumed for a god with no recorded attention")
    love_base: int = rule(20, 0, 100, RuleGroup.REPUTATION, "Base of love")
    love_loyalty_divisor: int = rule(4, 1, 100, RuleGroup.REPUTATION, "Loyalty contribution to love: loyalty / this number")
    love_per_unanswered_prayer: int = rule(6, 0, 100, RuleGroup.REPUTATION, "Love removed by each unanswered prayer")
    fear_base: int = rule(10, 0, 100, RuleGroup.REPUTATION, "Base of fear")
    fear_wrath_divisor: int = rule(3, 1, 100, RuleGroup.REPUTATION, "God's wrath contribution to fear: (wrath \u2212 default) / this number")
    chained_fear: int = rule(15, 0, 100, RuleGroup.REPUTATION, "Extra fear of a chained son")
    neglect_per_epoch: int = rule(12, 0, 100, RuleGroup.REPUTATION, "Contribution of each epoch without contact to neglect (forgottenness)")
    neglect_per_unanswered_prayer: int = rule(5, 0, 100, RuleGroup.REPUTATION, "Contribution of each unanswered prayer to neglect")
    attention_threshold: int = rule(40, 0, 100, RuleGroup.REPUTATION, "If the god's attention is below this, neglect rises")
    neglect_attention_divisor: int = rule(2, 1, 100, RuleGroup.REPUTATION, "Inattention contribution to neglect: missing attention / this number")
    forgotten_min_neglect: int = rule(60, 0, 100, RuleGroup.REPUTATION, 'Minimum neglect to count as "Forgotten"')
    forgotten_love_below: int = rule(50, 0, 100, RuleGroup.REPUTATION, 'Love must stay below this to count as "Forgotten"')
    forgotten_fear_below: int = rule(50, 0, 100, RuleGroup.REPUTATION, 'Fear must stay below this to count as "Forgotten"')
    hated_min_fear: int = rule(55, 0, 100, RuleGroup.REPUTATION, 'Minimum fear to count as "Hated"')
    hated_love_below: int = rule(35, 0, 100, RuleGroup.REPUTATION, 'Love must stay below this to count as "Hated"')
    hated_loyalty_below: int = rule(35, 0, 100, RuleGroup.REPUTATION, 'Loyalty must stay below this to count as "Hated"')
    respected_min_fear: int = rule(50, 0, 100, RuleGroup.REPUTATION, 'Minimum fear to count as "Respected"')
    respected_min_love: int = rule(50, 0, 100, RuleGroup.REPUTATION, 'Minimum love to count as "Respected"')
    feared_min_fear: int = rule(50, 0, 100, RuleGroup.REPUTATION, 'Minimum fear to count as "Feared"')
    loved_min_love: int = rule(55, 0, 100, RuleGroup.REPUTATION, 'Minimum love to count as "Loved"')
    distant_min_neglect: int = rule(40, 0, 100, RuleGroup.REPUTATION, 'Minimum neglect to count as "Distant"')
    loved_loyalty_gain: int = rule(2, 0, 50, RuleGroup.REPUTATION, "Loyalty gain per epoch of a son who loves the Creator")
    respected_loyalty_gain: int = rule(1, 0, 50, RuleGroup.REPUTATION, "Loyalty gain per epoch of a son who respects the Creator")
    respected_wrath_gain: int = rule(1, 0, 50, RuleGroup.REPUTATION, "Wrath gain per epoch of a son who respects the Creator")
    feared_wrath_gain: int = rule(2, 0, 50, RuleGroup.REPUTATION, "Wrath gain per epoch of a son who fears the Creator")
    hated_loyalty_loss: int = rule(2, 0, 50, RuleGroup.REPUTATION, "Loyalty loss per epoch of a son who hates the Creator")
    hated_wrath_gain: int = rule(3, 0, 50, RuleGroup.REPUTATION, "Wrath gain per epoch of a son who hates the Creator")
    forgotten_loyalty_loss: int = rule(2, 0, 50, RuleGroup.REPUTATION, "Loyalty loss per epoch of a forgotten son")
    distant_loyalty_loss: int = rule(1, 0, 50, RuleGroup.REPUTATION, "Loyalty loss per epoch of a son whose Creator is distant")
    rebel_loyalty_recovery: int = rule(
        4,
        0,
        50,
        RuleGroup.REPUTATION,
        "Loyalty a rebel son recovers per epoch (time closes the wound; reputation drift does not lower it during the rebellion)",
    )
    rebel_wrath_cooling: int = rule(2, 0, 50, RuleGroup.REPUTATION, "Wrath a rebel son cools per epoch")
    manual_push_keep_pct: int = rule(60, 0, 100, RuleGroup.REPUTATION, "Share of the god's manual push kept each epoch (%)")
    manual_push_floor: int = rule(2, 1, 100, RuleGroup.REPUTATION, "A manual push fading below this value is deleted")
    manual_push_cap: int = rule(60, 0, 100, RuleGroup.REPUTATION, "Maximum value of a manual push on each axis")
    manual_love_click: int = rule(10, 1, 100, RuleGroup.REPUTATION, 'Love push of one click on the "Win their heart" button in the son drawer')
    manual_fear_click: int = rule(10, 1, 100, RuleGroup.REPUTATION, 'Fear push of one click on the "Instil fear" button in the son drawer')
    manual_neglect_click: int = rule(15, 1, 100, RuleGroup.REPUTATION, "Push of one click on the make-forget button in the son drawer")
    power_trace_keep_pct: int = rule(60, 0, 100, RuleGroup.REPUTATION, "Share of the reputation trace left by the god's power that is kept each epoch (%)")
    power_trace_cap: int = rule(80, 0, 100, RuleGroup.REPUTATION, "Maximum value on each axis of the reputation trace left by the god's power")
    power_trace_floor: int = rule(2, 1, 100, RuleGroup.REPUTATION, "A god-power trace that decays below this is removed")
    drain_fear: int = rule(15, 0, 100, RuleGroup.REPUTATION, "Extra fear of a son whose essence is drained, toward the Creator")
    drain_love_loss: int = rule(12, 0, 100, RuleGroup.REPUTATION, "Love toward the Creator lost by a son whose essence is drained")
    drain_sibling_fear: int = rule(6, 0, 100, RuleGroup.REPUTATION, "Extra fear of siblings who witness essence draining")
    devour_sibling_fear: int = rule(20, 0, 100, RuleGroup.REPUTATION, "Extra fear of siblings who witness a son being devoured")
    devour_friend_love_loss: int = rule(15, 0, 100, RuleGroup.REPUTATION, "Love toward the Creator lost by those who loved the devoured son")
    demote_fear: int = rule(12, 0, 100, RuleGroup.REPUTATION, "Extra fear of a demoted (humbled) son")
    demote_love_loss: int = rule(12, 0, 100, RuleGroup.REPUTATION, "Love lost by a demoted son")
    demote_sibling_fear: int = rule(4, 0, 100, RuleGroup.REPUTATION, "Extra fear of those who see a sibling demoted")
    strip_power_fear: int = rule(10, 0, 100, RuleGroup.REPUTATION, "Extra fear of a son whose power is stripped")
    strip_power_love_loss: int = rule(8, 0, 100, RuleGroup.REPUTATION, "Love lost by a son whose power is stripped")
    strip_power_sibling_fear: int = rule(3, 0, 100, RuleGroup.REPUTATION, "Extra fear of those who see a sibling's power stripped")
